+static GList *
+append_to_list (struct context *context, GList *list, va_list valist)
+{
+  const char *val;
+  while (1)
+    {
+      val = va_arg (valist, const char *);
+      if (val == NULL)
+        break;
+      list = g_list_append (list, g_strdup (val));
+      context->total_elements++;
+    }
+  return list;
+}
