+static void
+do_linux (struct context *con, JsonNode *rootval)
+{
+  JsonObject *root = json_node_get_object (rootval);
+  if (json_object_has_member (root, "namespaces"))
+    {
+      JsonNode *namespaces;
+      GList *members;
+      GList *iter;
+      namespaces = json_object_get_member (root, "namespaces");
